begin;
set local time zone 'UTC';
\i supabase/tests/fixtures/external-canonical.sql
create function pg_temp.journey(event_name text,person text,days numeric,extras jsonb default '{}') returns jsonb language plpgsql as $$
declare packet jsonb;
begin
 packet:=jsonb_build_object('schema_version','2','environment','test','event_id',gen_random_uuid(),'event_name',event_name,'click_id','opaque_fixture_click_123456','subject_id',person,'dedupe_key',event_name||':'||person||':'||days::text,'occurred_at',to_char(statement_timestamp()-make_interval(secs=>(days*86400)::double precision),'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))||extras;
 return public.ingest_funnel_metric_event('ac570000-0000-4000-8000-000000000001','ac570000-0000-4000-8000-000000000002',packet);
end;$$;
select set_config('qa.journey.report',jsonb_build_object('product_id','ac570000-0000-4000-8000-000000000001','funnel_id','ac570000-0000-4000-8000-000000000002','date_from',(current_date-25)::text,'date_to',current_date::text,'time_zone','UTC','environment','test','conversion_window_days',30)::text,true);
select pg_temp.journey('landing_page_viewed','guest_subject_123456789',18);
select pg_temp.journey('lead_created','guest_subject_123456789',17);
select pg_temp.journey('identity_linked','verified_subject_123456789',16,'{"aliased_subject_id":"guest_subject_123456789","state_value":"verified"}');
select pg_temp.journey('email_verified','verified_subject_123456789',16);
select pg_temp.journey('assessment_started','verified_subject_123456789',15);
select pg_temp.journey('assessment_completed','verified_subject_123456789',14);
select pg_temp.journey('availability_saved','verified_subject_123456789',13);
select pg_temp.journey('webinar_invitation_requested','verified_subject_123456789',12,'{"request_source":"resources"}');
select pg_temp.journey('webinar_registered','verified_subject_123456789',11,'{"webinar_id":"webinar_one"}');
select pg_temp.journey('webinar_registered','verified_subject_123456789',10.5,'{"webinar_id":"webinar_missed"}');
select pg_temp.journey('webinar_attendance_updated','verified_subject_123456789',9.5,'{"webinar_id":"webinar_missed","state_value":"missed","state_revision":"1"}');
select pg_temp.journey('webinar_join_clicked','verified_subject_123456789',10,'{"webinar_id":"webinar_one"}');
select pg_temp.journey('webinar_attendance_updated','verified_subject_123456789',9,'{"webinar_id":"webinar_one","state_value":"unknown","state_revision":"1"}');
set local role authenticated;
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)#>>'{journey,learners,leads}'='1','lead identity preserved through verification without duplicate');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)#>>'{journey,learners,visitors}'='1','anonymous arrival linked to verified learner');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)#>>'{journey,learners,attended}'='0','join clicks do not prove attendance');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb||'{"webinar_id":"webinar_one"}')#>>'{journey,learners,attendance_unknown}'='1','unknown attendance is separate');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)#>>'{journey,valid_clicks}'='1','valid classified click counted once');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb||'{"environment":"live"}')#>>'{journey,valid_clicks}'='0','test traffic never included in live');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb||jsonb_build_object('date_from',current_date::text))#>>'{journey,learners,leads}'='0','old cohort not counted as a new lead today');
select pg_temp.reject('select * from public.funnel_journey_identities','creator/browser cannot read raw identities');
reset role;
-- Deterministic business key deduplicates a retry even with a fresh transport UUID.
select set_config('qa.packet',jsonb_build_object('schema_version','2','environment','test','event_id',gen_random_uuid(),'event_name','resource_served','click_id','opaque_fixture_click_123456','subject_id','verified_subject_123456789','dedupe_key','resource:one:verified','occurred_at',to_char(clock_timestamp(),'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text,true);
select public.ingest_funnel_metric_event('ac570000-0000-4000-8000-000000000001','ac570000-0000-4000-8000-000000000002',current_setting('qa.packet')::jsonb);
select pg_temp.check_true(public.ingest_funnel_metric_event('ac570000-0000-4000-8000-000000000001','ac570000-0000-4000-8000-000000000002',current_setting('qa.packet')::jsonb||jsonb_build_object('event_id',gen_random_uuid()))->>'duplicate'='true','business retries dedupe across changed event ID');
select pg_temp.reject('select public.ingest_funnel_metric_event(''ac570000-0000-4000-8000-000000000001'',''ac570000-0000-4000-8000-000000000002'',current_setting(''qa.packet'')::jsonb||''{"resource_id":"changed"}'')','duplicate business evidence cannot mutate');
select pg_temp.reject('select pg_temp.journey(''purchase_completed'',''verified_subject_123456789'',0)','generic telemetry cannot create purchases');
select pg_temp.reject('select pg_temp.journey(''identity_linked'',''other_verified_subject_123456'',0,''{"aliased_subject_id":"verified_subject_123456789","state_value":"verified"}'')','verified identities cannot be merged arbitrarily');
-- Authoritative merchant payments link through the opaque external order reference.
select pg_temp.make_order(1,8000,false,statement_timestamp()-interval '3 days');
select pg_temp.journey('checkout_created','verified_subject_123456789',4,jsonb_build_object('order_id',(select core#>>'{input,order_id}' from test_external_orders where n=1)));
select pg_temp.journey('matching_pool_entered','verified_subject_123456789',2);
select pg_temp.journey('group_confirmed','verified_subject_123456789',1);
select public.process_external_commissions();
select pg_temp.journey('webinar_attendance_updated','verified_subject_123456789',10,'{"webinar_id":"webinar_one","state_value":"attended","state_revision":"2"}');
-- Older delayed unknown must never replace the later confirmed host evidence.
select pg_temp.journey('webinar_attendance_updated','verified_subject_123456789',8.5,'{"webinar_id":"webinar_one","state_value":"unknown","state_revision":"1"}');
set local role authenticated;
select set_config('qa.journey.result',public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)::text,true);
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,learners,paid}'='1','paid learner follows verified order not redirect');
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,learners,matching_pool}'='1','paid pool is not group confirmation');
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,learners,attended}'='1','confirmed attendance wins over delayed older unknown');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb||'{"webinar_id":"webinar_missed"}')#>>'{journey,learners,attended}'='0','another webinar attendance does not leak into a missed webinar filter');
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,commerce,0,approved_commission_minor}'='2000','approved commission reuses canonical signed rule');
select pg_temp.check_true((current_setting('qa.journey.result')::jsonb#>>'{journey,commerce,0,approved_epc_minor}')::numeric=2000,'EPC uses approved earnings divided by valid cohort clicks');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb||'{"currency":"EUR"}')#>'{journey,commerce}'='[]'::jsonb,'currencies cannot mix');
reset role;
-- Successful partial refunds count distinct orders, not two refund notifications.
select public.record_external_commission_adjustment(jsonb_build_object('order_id',(select order_id from test_external_orders where n=1),'provider_event_id','evt_journeyrefundone','kind','refund','refund_id','re_journeyone','amount_minor',1000,'occurred_at',statement_timestamp()-interval '1 day'));
select public.record_external_commission_adjustment(jsonb_build_object('order_id',(select order_id from test_external_orders where n=1),'provider_event_id','evt_journeyrefundtwo','kind','refund','refund_id','re_journeytwo','amount_minor',2000,'occurred_at',statement_timestamp()));
set local role authenticated;
select set_config('qa.journey.result',public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)::text,true);
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,commerce,0,refunded_orders}'='1','two partial refunds are one refunded order');
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,commerce,0,refunded_minor}'='3000','partial refunded revenue is authoritative sum');
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,commerce,0,approved_commission_minor}'='1400','refund reversal reduces original earned amount');
select pg_temp.check_true(current_setting('qa.journey.result')::jsonb#>>'{journey,commerce,0,reversed_commission_minor}'='600','reversals shown separately');
reset role;
select pg_temp.ready_account('acct_fixture');
select set_config('qa.journey.batch',pg_temp.prepare_approved('acct_fixture')::text,true);
select set_config('qa.journey.job',(select value::text from public.claim_creator_transfer_jobs('acct_fixture',false) value),true);
select public.begin_creator_transfer_attempt(jsonb_build_object('id',current_setting('qa.journey.job')::jsonb->>'id','lease_token',current_setting('qa.journey.job')::jsonb->>'lease_token'));
select public.finish_creator_transfer_job(current_setting('qa.journey.job')::jsonb||jsonb_build_object('status','succeeded','provider_id','tr_journeyfixture'));
set local role authenticated;
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)#>>'{journey,commerce,0,approved_commission_minor}'='1400','payout never adds a second earning');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)#>>'{journey,commerce,0,paid_commission_minor}'='1400','completed transfer is separately reported as subset');
select set_config('request.jwt.claims','{"sub":"ac570000-0000-4000-8000-000000000012","role":"authenticated"}',true);
select pg_temp.check_true(public.get_partner_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)#>>'{journey,learners,leads}'='1','creator can inspect own aggregate');
select pg_temp.reject('select public.get_partner_funnel_metrics_report(current_setting(''qa.journey.report'')::jsonb||''{"affiliate_id":"ac570000-0000-4000-8000-000000000014"}'')','creator cannot switch report identity');
select pg_temp.reject('select public.configure_admin_funnel_journey(''{"funnel_id":"ac570000-0000-4000-8000-000000000002","environment":"test"}'')','creator cannot change tracking environment');
select pg_temp.admin();
select set_config('qa.journey.config',public.configure_admin_funnel_journey('{"funnel_id":"ac570000-0000-4000-8000-000000000002","environment":"test","conversion_window_days":21}')::text,true);
select pg_temp.check_true(public.get_admin_funnel_journey_configuration('ac570000-0000-4000-8000-000000000002')->>'environment'='test','environment is explicitly configurable');
select pg_temp.reject('select public.configure_admin_funnel_journey(''{"funnel_id":"ac570000-0000-4000-8000-000000000002","environment":"live"}'')','configuration requires optimistic version guard');
select pg_temp.check_true(public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb-'conversion_window_days')#>>'{journey,conversion_window_days}'='21','configured reporting window applies without changing commission policy');
reset role;
-- Mutually exclusive ordered purchase paths, while pay-first remains supported.
select pg_temp.make_order(2,8000,false,statement_timestamp()-interval '5 days');
select pg_temp.journey('checkout_created','pay_first_subject_123456',6,jsonb_build_object('order_id',(select core#>>'{input,order_id}' from test_external_orders where n=2)));
select pg_temp.journey('lead_created','pay_first_subject_123456',4);
select pg_temp.journey('assessment_started','pay_first_subject_123456',3);
select pg_temp.journey('assessment_completed','pay_first_subject_123456',2);
select pg_temp.make_order(3,8000,false,statement_timestamp()-interval '1 day');
select pg_temp.journey('lead_created','recovered_subject_123456',12);
select pg_temp.journey('checkout_created','recovered_subject_123456',11,jsonb_build_object('order_id',(select core#>>'{input,order_id}' from test_external_orders where n=3)));
select pg_temp.journey('checkout_cancel_returned','recovered_subject_123456',10);
select pg_temp.journey('webinar_invitation_requested','recovered_subject_123456',9,'{"request_source":"checkout_cancelled"}');
select pg_temp.journey('webinar_registered','recovered_subject_123456',8,'{"webinar_id":"recovery_webinar"}');
select pg_temp.journey('webinar_attendance_updated','recovered_subject_123456',7,'{"webinar_id":"recovery_webinar","state_value":"attended","state_revision":"1"}');
set local role authenticated;
select set_config('qa.journey.paths',public.get_admin_funnel_metrics_report(current_setting('qa.journey.report')::jsonb)::text,true);
select pg_temp.check_true((select (p->>'orders')::integer=1 from jsonb_array_elements(current_setting('qa.journey.paths')::jsonb#>'{journey,paths}') p where p->>'key'='pay_first'),'post-purchase assessment never misclassified as assessment then payment');
select pg_temp.check_true((select (p->>'orders')::integer=1 from jsonb_array_elements(current_setting('qa.journey.paths')::jsonb#>'{journey,paths}') p where p->>'key'='cancelled_webinar_payment'),'cancel request registration attendance purchase ordered recovery');
select pg_temp.check_true((select sum((p->>'orders')::integer)=3 from jsonb_array_elements(current_setting('qa.journey.paths')::jsonb#>'{journey,paths}') p),'each paid order occupies exactly one primary path');
reset role;
rollback;
